//! CKB-zkVM Parallel Proof Verification CLI (SP1 Hypercube v6 — 64-bit)
//!
//! Verifies a zero-knowledge proof generated by `prove-parallel`.
//!
//! Usage:
//!   verify-parallel <PROOF_PATH> [--vkey <PATH>] [--expected-hash <HASH>]

use std::path::PathBuf;
use std::time::Instant;

use anyhow::{anyhow, Context, Result};
use clap::Parser;
use sp1_sdk::{Prover, ProverClient, ProvingKey, SP1ProofWithPublicValues, SP1VerifyingKey};
use tracing::{info, Level};
use tracing_subscriber::FmtSubscriber;

use ckb_zkvm_lib::{parse_h256, PublicValues};
use ckb_zkvm_host_64_parallel::logging::log_public_values;

/// CLI arguments for the verify command.
#[derive(Parser, Debug)]
#[command(name = "verify-parallel")]
#[command(about = "Verify a ZK proof generated by prove-parallel")]
struct Args {
    /// Path to the proof file (proof.bin)
    #[arg(value_name = "PROOF")]
    proof_path: PathBuf,

    /// Path to the verifying key file (vkey.bin from prove-parallel output)
    #[arg(long, short)]
    vkey: Option<PathBuf>,

    /// Path to the aggregation guest ELF (derives VK if --vkey not provided)
    #[arg(long, default_value = "")]
    elf: PathBuf,

    /// Expected transaction hash (optional, for additional validation)
    #[arg(long)]
    expected_hash: Option<String>,
}

#[tokio::main]
async fn main() -> Result<()> {
    dotenvy::dotenv().ok();

    let _subscriber = FmtSubscriber::builder()
        .with_max_level(Level::INFO)
        .with_target(false)
        .init();

    let args = Args::parse();

    info!("CKB-zkVM Parallel Proof Verifier (SP1 Hypercube v6, 64-bit)");
    info!("=============================================================");
    info!("Proof: {}", args.proof_path.display());

    // Step 1: Load proof
    info!("Step 1: Loading proof...");
    let start = Instant::now();

    let proof_bytes =
        std::fs::read(&args.proof_path).context("failed to read proof file")?;

    let proof: SP1ProofWithPublicValues =
        bincode::deserialize(&proof_bytes).context("failed to deserialize proof")?;

    info!("Proof loaded in {:?}", start.elapsed());

    // Step 2: Extract public values
    info!("Step 2: Extracting public values...");

    let public_values = PublicValues::from_bytes(proof.public_values.as_slice())
        .ok_or_else(|| anyhow!("failed to decode public values"))?;

    log_public_values(&public_values);

    // Step 3: Validate expected hash if provided
    if let Some(expected) = &args.expected_hash {
        info!("Step 3: Validating transaction hash...");

        let expected_hash = parse_h256(expected).context("invalid expected hash")?;

        if public_values.tx_hash != expected_hash {
            return Err(anyhow!(
                "transaction hash mismatch: expected 0x{}, got 0x{}",
                hex::encode(expected_hash),
                hex::encode(public_values.tx_hash)
            ));
        }

        info!("Transaction hash matches expected value");
    }

    // Step 4: Load verifying key
    info!("Step 4: Loading verifying key...");

    let vk: SP1VerifyingKey = if let Some(vkey_path) = &args.vkey {
        let vkey_bytes =
            std::fs::read(vkey_path).context("failed to read vkey file")?;
        bincode::deserialize(&vkey_bytes).context("failed to deserialize vkey")?
    } else if args.elf.as_os_str().is_empty() {
        // Try default path: same directory as proof
        let default_vkey = args.proof_path.parent()
            .unwrap_or(std::path::Path::new("."))
            .join("vkey.bin");
        if default_vkey.exists() {
            info!("Using vkey from: {}", default_vkey.display());
            let vkey_bytes =
                std::fs::read(&default_vkey).context("failed to read vkey file")?;
            bincode::deserialize(&vkey_bytes).context("failed to deserialize vkey")?
        } else {
            return Err(anyhow!(
                "no verifying key found. Provide --vkey <path> or place vkey.bin alongside the proof"
            ));
        }
    } else {
        info!("Deriving VK from aggregation ELF at {}...", args.elf.display());
        let elf_bytes = std::fs::read(&args.elf)
            .with_context(|| format!("failed to read ELF from {}", args.elf.display()))?;
        let client = ProverClient::from_env().await;
        let elf = sp1_sdk::Elf::Dynamic(elf_bytes.into());
        let pk = client.setup(elf).await
            .context("SP1 setup failed")?;
        pk.verifying_key().clone()
    };

    // Step 5: Verify proof
    info!("Step 5: Verifying proof...");
    let start = Instant::now();

    let client = ProverClient::from_env().await;
    client
        .verify(&proof, &vk, None)
        .context("proof verification failed")?;

    info!("Proof verified in {:?}", start.elapsed());

    // Step 6: Report result
    info!("=============================================================");

    if public_values.is_success() {
        info!("VALID: Proof confirms successful execution of transaction");
        info!("  Transaction: 0x{}", hex::encode(public_values.tx_hash));
        info!("  Script groups: {}", public_values.script_results.len());
        info!("  Cycles: {}", public_values.cycles);
    } else {
        info!(
            "VALID: Proof confirms execution with exit code {}",
            public_values.exit_code
        );
    }

    Ok(())
}
